function filter_core_rules_user($fw)
{
    global $config;

    foreach ((new \OPNsense\Firewall\Group())->ifgroupentry->iterateItems() as $node) {
        $ifgroups[(string)$node->ifname] = !empty((string)$node->sequence) ? (string)$node->sequence : 0;
    }

    if (isset($config['filter']['rule'])) {
        // register user rules
        foreach ($config['filter']['rule'] as $idx => $rule) {
            if (!is_array($rule)) {
                continue;
            }
            // calculate a hash for this area so we can track this rule, we should replace this
            // with uuid's on the rules like the new style models do eventually.
            $rule['label'] = OPNsense\Firewall\Util::calcRuleHash($rule);

            $intf = !empty($rule['floating']) ? 'FloatingRules' : $rule['interface'];
            $rule['#ref'] = sprintf('firewall_rules_edit.php?if=%s&id=%s', $intf, $idx);
            $rule['seq'] = $idx;  // current rule sequence (used as id in firewall pages)

            if (empty($rule['descr'])) {
                $rule['descr'] = '';
            }

            if (isset($rule['floating'])) {
                $prio = 200000;
            } elseif (isset($ifgroups[$rule['interface']])) {
                $prio = 300000 + $ifgroups[$rule['interface']];
            } else {
                $prio = 400000;
            }
            $fw->registerFilterRule($prio, $rule);
        }
    }
}

/**
 * fetch anchors as text (pf ruleset part)
 * @param string $types anchor types (fw for filter, other options are nat,rdr,binat. comma-separated)
 * @param string $placement placement head,tail
 * @return string
 */
public function anchorToText($types = "fw", $placement = "tail")
{
    $result = "";
    foreach (explode(',', $types) as $type) {
        foreach ($this->anchors as $anchorKey => $anchor) {
            if (strpos($anchorKey, "{$type}.{$placement}") === 0) {
                $result .= $type == "fw" ? "" : "{$type}-";
                $result .= "anchor \"{$anchor['name']}\"";
                if ($anchor['quick']) {
                    $result .= " quick";
                }
                $result .= "\n";
            }
        }
    }
    return $result;
}

/**
 * register a filter rule
 * @param int $prio priority
 * @param array $conf configuration
 * @param array $defaults merge these defaults when provided
 */
public function registerFilterRule($prio, $conf, $defaults = null)
{
    if (!empty($this->systemDefaults['filter'])) {
        $conf = array_merge($this->systemDefaults['filter'], $conf);
    }
    if ($defaults != null) {
        $conf = array_merge($defaults, $conf);
    }
    if (empty($conf['label'])) {
        // generated rule, has no label
        $rule_hash = Util::calcRuleHash($conf);
        $conf['label'] = $rule_hash;
    }
    $conf['#priority'] = $prio;
    $rule = new FilterRule($this->interfaceMapping, $this->gatewayMapping, $conf);
    if (empty($this->filterRules[$prio])) {
        $this->filterRules[$prio] = [];
    }
    $this->filterRules[$prio][] = $rule;
}

/**
 * register a Forward (rdr) rule
